  // ── Safety Properties (SVA) ──

  // Enforce reset sequence for formal verification
  reg f_past_valid = 0;
  always_ff @(posedge clk) begin
    f_past_valid <= 1;
  end
  always_comb begin
    if (!f_past_valid) assume (!rst_n);
  end

  // source: <unknown>:264
  // property: system_stability
  always @(posedge clk) begin
    if (rst_n) begin
      system_stability: assert((((robot_angle < (-(-100000))) & (robot_angle > (-100000))) & (global_trap == 1'b0)));
    end
  end

endmodule
